mapper.sql:
AND EXISTS ( SELECT 1 FROM lb_merchant_entry me WHERE me.tenant_id = o.tenant_id AND me.merchant_id = o.merchant_id AND me.status = 'APPROVED' AND me.deleted = b'0' AND me.id = ( SELECT MAX(me_latest.id) FROM lb_merchant_entry me_latest WHERE me_latest.tenant_id = me.tenant_id AND me_latest.merchant_id = me.merchant_id AND me_latest.status = 'APPROVED' AND me_latest.deleted = b'0' ) AND me.region_code IN
#{regionCode}
)

AND a.adcode IN
#{regionCode}
AND NOT EXISTS ( SELECT 1 FROM lb_user_address preferred WHERE preferred.tenant_id = a.tenant_id AND preferred.user_id = a.user_id AND preferred.deleted = b'0' AND ( preferred.is_default > a.is_default OR (preferred.is_default = a.is_default AND preferred.id < a.id) ) )

mapper.select:
SELECT dispute.dispute_type, dispute.dispute_id, dispute.dispute_no, dispute.order_id, dispute.order_no, dispute.unit_id, dispute.unit_no, dispute.region_code, dispute.status, dispute.content, dispute.result_desc, dispute.create_time FROM (
UNION ALL
) dispute WHERE 1 = 1
AND dispute.status = #{reqVO.status}
AND dispute.region_code = #{reqVO.regionCode}
AND (dispute.order_no LIKE CONCAT('%', #{reqVO.keyword}, '%') OR dispute.dispute_no LIKE CONCAT('%', #{reqVO.keyword}, '%'))
ORDER BY dispute.create_time DESC, dispute.dispute_id DESC

SELECT order_stats.order_count, order_stats.trade_amount, ( SELECT COUNT(*) FROM lb_complaint c INNER JOIN lb_order_info o ON o.id = c.order_id AND o.tenant_id = c.tenant_id AND o.deleted = b'0' WHERE c.deleted = b'0' AND c.status IN ('PENDING', 'PROCESSING')
) + ( SELECT COUNT(*) FROM lb_appeal ap INNER JOIN lb_order_info o ON o.id = ap.order_id AND o.tenant_id = ap.tenant_id AND o.deleted = b'0' WHERE ap.deleted = b'0' AND ap.status IN ('PENDING', 'PROCESSING')
) AS pending_dispute_count FROM ( SELECT COUNT(*) AS order_count, COALESCE(SUM(o.order_amount), 0) AS trade_amount FROM lb_order_info o WHERE o.deleted = b'0'
) order_stats
